// @ts-nocheck -- route search types are generated by the embedded app.
import { useQuery } from "@tanstack/react-query";
import { createFileRoute, Link, redirect } from "@tanstack/react-router";
import { FileText } from "lucide-react";
import { MreTable } from "@/features/audit/learner-log-pro/components/MreTable";
import { getLearnerActivities } from "@/features/audit/learner-log-pro/lib/api";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/features/audit/learner-log-pro/components/ui/table";

export const Route = createFileRoute("/activity")({
  validateSearch: (search: Record<string, unknown>) => ({
    learner: typeof search.learner === "string" ? search.learner : "",
    plan: typeof search.plan === "string" ? search.plan : "",
  }),
  beforeLoad: ({ search }) => {
    if (!search.plan) throw redirect({ to: "/search" });
  },
  component: ActivityLogPage,
});

function ActivityLogPage() {
  const { learner, plan } = Route.useSearch();
  const overview = useQuery({
    queryKey: ["activity-overview", learner, plan],
    queryFn: () => getLearnerActivities({
      learner: plan ? undefined : learner || undefined,
      search: plan || "",
      limit: plan ? 100 : 1,
      offset: 0,
    }),
  });
  const attendanceRows = plan
    ? (overview.data?.items ?? []).filter((item) => item.plan_id === plan)
    : [];
  const activity = attendanceRows[0] ?? overview.data?.items[0];
  const ksbs = activity?.key_ksbs?.split(",").map((value) => value.trim()).filter(Boolean) ?? [];
  const gap = activity ? (activity.actual_lms_hours ?? 0) - (activity.planned_hours ?? 0) : 0;
  const totalActualHours = attendanceRows.reduce((sum, item) => sum + (item.actual_lms_hours ?? 0), 0);

  return (
    <div className="min-h-screen bg-background">
      <header className="border-b border-border bg-surface">
        <div className="mx-auto flex max-w-[88rem] flex-wrap items-center justify-between gap-4 px-6 py-4">
          <div className="flex items-baseline gap-3">
            <span className="font-serif text-base text-foreground">OTJ&nbsp;Ledger</span>
            <span className="label-caps">Live off-the-job activity</span>
          </div>
          <div className="flex items-center gap-4 text-xs text-muted-foreground">
            {activity && <span className="font-mono">{activity.month_unit}</span>}
            <Link to="/search" className="font-medium text-foreground hover:underline">Search</Link>
            <Link
              to="/journal"
              search={{
                learner: learner || activity?.learner.toLowerCase() || "",
                period: activity?.activity_period || "",
              }}
              className="font-medium text-foreground hover:underline"
            >
              Monthly learner journal →
            </Link>
            <span className="rounded-sm border border-success/40 bg-success/10 px-2 py-1 font-semibold text-success">Live data</span>
          </div>
        </div>
      </header>

      <main className="mx-auto max-w-[88rem] space-y-6 px-6 py-8">
        {overview.isLoading && (
          <div className="rounded-lg border border-border bg-card px-7 py-16 text-center text-sm text-muted-foreground">Loading activity from Neon…</div>
        )}
        {overview.isError && (
          <div className="rounded-lg border border-border bg-card px-7 py-16 text-center text-sm text-destructive">
            {overview.error instanceof Error ? overview.error.message : "Could not load activity."}
          </div>
        )}
        {activity && (
          <div className="grid gap-6 lg:grid-cols-3">
            <article className="rounded-lg border border-border bg-card shadow-panel lg:col-span-2">
              <header className="border-b border-border px-7 py-6">
                <div className="flex flex-wrap items-center gap-2">
                  <span className="rounded-sm bg-primary px-2 py-1 text-xs font-semibold text-primary-foreground">{activity.activity_category}</span>
                  <span className="label-caps">{activity.plan_id} · {activity.week_sequence}</span>
                </div>
                <h1 className="mt-3 font-serif text-2xl text-foreground">{activity.activity_unit}</h1>
              </header>
              <div className="space-y-6 px-7 py-6">
                <section>
                  <h2 className="font-serif text-base text-foreground">Activity description</h2>
                  <p className="mt-2 text-sm leading-7 text-muted-foreground">{activity.activity_description}</p>
                </section>
                <div className="grid gap-5 border-t border-border pt-5 sm:grid-cols-2">
                  <section>
                    <h2 className="label-caps">Expected evidence</h2>
                    <p className="mt-2 text-sm leading-6 text-foreground">{activity.expected_evidence || "Not specified"}</p>
                  </section>
                  <section>
                    <h2 className="label-caps">Delivery and source</h2>
                    <p className="mt-2 text-sm text-foreground">{activity.delivery_method}</p>
                    <p className="mt-1 text-xs text-muted-foreground">{activity.source_course || activity.source_basis || "MRE learning plan"}</p>
                  </section>
                </div>
              </div>
            </article>

            <aside className="activity-snapshot overflow-hidden rounded-lg border border-border bg-card shadow-panel">
              <header className="bg-primary px-6 py-5 text-primary-foreground">
                <p className="snapshot-label label-caps">Activity snapshot</p>
                <h2 className="mt-1 font-serif text-xl font-bold text-primary-foreground">{plan ? "Attendance overview" : activity.learner}</h2>
              </header>
              <dl className="grid gap-5 px-6 py-6">
                {plan ? (
                  <>
                    <div><dt className="label-caps">Learners recorded</dt><dd className="snapshot-value mt-1 font-mono">{attendanceRows.length}</dd></div>
                    <div><dt className="label-caps">Total actual hours</dt><dd className="snapshot-value mt-1 font-mono">{totalActualHours.toFixed(2)}h</dd></div>
                  </>
                ) : (
                  <>
                    <div><dt className="label-caps">Learner activity date</dt><dd className="snapshot-value mt-1 font-mono">{activity.learner_activity_date ?? "Not recorded"}</dd></div>
                    <div><dt className="label-caps">Timestamp</dt><dd className="snapshot-value mt-1 font-mono">{activity.time_from_to ?? "Not recorded"}</dd></div>
                  </>
                )}
                <div><dt className="label-caps">Planned date</dt><dd className="snapshot-value mt-1 font-mono">{activity.unit_planned_date}</dd></div>
                <div>
                  <dt className="label-caps">Mapped KSBs</dt>
                  <dd className="mt-2 flex flex-wrap gap-2">
                    {ksbs.length ? ksbs.map((ksb) => <span key={ksb} className="rounded border border-border bg-muted px-2 py-1 font-mono text-xs">{ksb}</span>) : "Not specified"}
                  </dd>
                </div>
                <div className="grid grid-cols-3 gap-3 border-t border-border pt-5">
                  <div><dt className="label-caps">Planned</dt><dd className="mt-1 font-mono text-lg">{activity.planned_hours ?? 0}h</dd></div>
                  <div><dt className="label-caps">Actual</dt><dd className="mt-1 font-mono text-lg text-success">{activity.actual_lms_hours ?? 0}h</dd></div>
                  <div><dt className="label-caps">Gap</dt><dd className={`mt-1 font-mono text-lg ${gap < 0 ? "text-warning" : "text-success"}`}>{gap > 0 ? "+" : ""}{gap.toFixed(2)}h</dd></div>
                </div>
              </dl>
            </aside>
          </div>
        )}

        {plan && activity && (
          <section className="rounded-lg border border-border bg-card shadow-panel">
            <header className="flex flex-wrap items-end justify-between gap-4 border-b border-border px-7 py-5">
              <div>
                <h2 className="font-serif text-xl text-foreground">Learner attendance log</h2>
                <p className="mt-1 text-sm text-muted-foreground">
                  Learners with an activity date, timestamp or actual hours recorded against <span className="font-mono">{plan}</span>.
                </p>
              </div>
              <dl className="flex gap-6">
                <div><dt className="label-caps">Attendees</dt><dd className="font-mono text-base font-semibold">{attendanceRows.length}</dd></div>
                <div><dt className="label-caps">Actual hours</dt><dd className="font-mono text-base font-semibold text-success">{totalActualHours.toFixed(2)}h</dd></div>
              </dl>
            </header>
            <div className="overflow-x-auto">
              <Table>
                <TableHeader>
                  <TableRow className="hover:bg-transparent">
                    <TableHead className="label-caps pl-7">Learner</TableHead>
                    <TableHead className="label-caps">Activity date</TableHead>
                    <TableHead className="label-caps">Timestamp</TableHead>
                    <TableHead className="label-caps text-right">Planned hours</TableHead>
                    <TableHead className="label-caps text-right">Actual hours</TableHead>
                    <TableHead className="label-caps pr-7 text-right">Details</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {attendanceRows.map((row) => (
                    <TableRow key={row.id}>
                      <TableCell className="pl-7 text-sm font-semibold text-foreground">{row.learner}</TableCell>
                      <TableCell className="font-mono text-sm">{row.learner_activity_date ?? "—"}</TableCell>
                      <TableCell className="font-mono text-sm">{row.time_from_to ?? "—"}</TableCell>
                      <TableCell className="text-right font-mono text-sm">{row.planned_hours?.toFixed(2) ?? "—"}</TableCell>
                      <TableCell className="text-right font-mono text-sm text-success">{row.actual_lms_hours?.toFixed(2) ?? "—"}</TableCell>
                      <TableCell className="pr-7 text-right">
                        <Link
                          to="/journal"
                          search={{
                            learner: row.learner.toLowerCase(),
                            period: row.activity_period ?? "",
                          }}
                          className="inline-flex items-center gap-1.5 text-xs font-semibold text-primary hover:underline"
                        >
                          <FileText className="h-3.5 w-3.5" aria-hidden />
                          View activity
                        </Link>
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </div>
          </section>
        )}

        {!plan && <MreTable learner={learner || undefined} />}
        <p className="pb-4 text-xs text-muted-foreground">
          All values on this page are loaded from the Neon <span className="font-mono">Audit.mre</span> table.
        </p>
      </main>
    </div>
  );
}
